       v.finish, v.lang, v.quantity, v.name, v.type_line, v.mana_cost, v.mana_value::numeric,
       v.color_identity, v.oracle_text, v.rarity, v.set_code, v.set_name, v.collector_number,
       v.image_url, v.commander_legal, v.can_be_commander
