-- The PipGlyph card the Meren deck proxies: dev_artist's public saga.
insert into public.deck_cards (id, deck_id, board, quantity, position, card_id, source, name, type_line, mana_cost, mana_value, color_identity, rarity)
select 'a0000000-0000-4000-a000-000000009051'::uuid, 'b0000000-0000-4000-a000-000000000031'::uuid, 'main', 1, 60,
       c.id, 'link', c.title, 'Enchantment — Saga', '{2}{B}{G}', 4, array['B','G'], 'rare'
from public.cards c
where c.id = 'c0000000-0000-4000-a000-000000000012'
  and c.visibility = 'public'
  and exists (select 1 from public.decks where id = 'b0000000-0000-4000-a000-000000000031')
on conflict (id) do nothing;
